/** 문단의 순수 텍스트(링크 조각을 이어 붙인 결과).
 * 읽기시간 계산과 가시 텍스트 불변식 검증이 이 함수를 공유한다.
 * (docs/design/blog-inline-links-spec-2026-08-04.md §1-1·§2-3) */
export function paragraphPlainText(section: {
  text?: string;
  segments?: BlogInlineSegment[];
}): string {
  return section.segments ? section.segments.map((s) => s.text).join("") : section.text ?? "";
}

/** 본문 인라인 내부링크의 빌드 타임 검증(스펙 §3-2).
 * blogPosts는 정적 배열이고 /blog/[slug]가 generateStaticParams로 전량 SSG되므로,
 * next build가 이 모듈을 import하는 순간 검증이 돌고 실패하면 빌드가 죽는다.
 * 빌드가 통과하면 데이터가 정적으로 고정되므로 런타임에는 throw할 수 없다.
 * 🔴 process.env.NODE_ENV 가드를 붙이지 마라 — next build는 production이라 게이트가 통째로 무력화된다. */
function validateBlogInternalLinks(): void {
  const slugs = new Set(blogPosts.map((p) => p.slug));
  for (const post of blogPosts) {
    for (const section of post.body) {
      if (section.type !== "paragraph" || !section.segments) continue;
      for (const seg of section.segments) {
        if (!seg.slug) continue;
        if (!/^[a-z0-9-]+$/.test(seg.slug))
          throw new Error(`blog: 잘못된 slug 형식 ${post.slug} → ${seg.slug}`);
        if (!slugs.has(seg.slug))
          throw new Error(`blog: 없는 글로 가는 링크 ${post.slug} → ${seg.slug}`);
        if (seg.slug === post.slug) throw new Error(`blog: 자기 자신을 링크 ${post.slug}`);
        if (!seg.text.trim()) throw new Error(`blog: 링크 텍스트가 비었다 ${post.slug} → ${seg.slug}`);
      }
    }
  }
}
validateBlogInternalLinks();

/** 발행일 최신순 정렬된 전체 글 목록 */
export function getBlogPosts(): BlogPost[] {
  // 내림차순(최신순). 문자열 비교이므로 동률(같은 날짜)일 때 0을 반환해야 comparator 계약을 지킨다
  // (이전엔 항상 -1/1만 반환해 동률 시 대칭성이 깨지는 버그가 있었음).
  return [...blogPosts].sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
}

/** slug로 글 1개 조회. 없으면 undefined */
export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find((post) => post.slug === slug);
}

/** 카테고리별 글 목록(발행일 최신순) */
export function getBlogPostsByCategory(category: BlogCategory): BlogPost[] {
  return getBlogPosts().filter((post) => post.category === category);
}

/** 실제로 글이 1편 이상 있는 카테고리만 반환 (docs/design/blog.md §1-2 "글이 있는 카테고리만 탭 렌더") */
export function getActiveBlogCategories(): BlogCategory[] {
  const order: BlogCategory[] = ["guide", "insight", "howto", "market"];
  return order.filter((category) => blogPosts.some((post) => post.category === category));
}

/** "YYYY-MM-DD" → "YYYY. M. D." (한국어 로케일 날짜 표기, docs/design/blog.md 예시와 동일).
 * Date 객체를 거치지 않아 빌드 서버 타임존에 따른 날짜 밀림이 없다. */
export function formatBlogDateKo(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  return `${y}. ${m}. ${d}.`;
}

/** 본문 총 글자 수 기반 예상 읽기시간(분). 한국어 평균 독서 속도(분당 약 450자) 기준, 최소 1분. */
export function getReadingMinutes(post: BlogPost): number {
  const totalChars = post.body.reduce((sum, section) => {
    // 🔴 paragraph는 segments를 반드시 세야 한다(`?? ""`로 넘기면 읽기시간이 줄어든다, 스펙 §2-4·§7-2-4).
    if (section.type === "paragraph") return sum + paragraphPlainText(section).length;
    if (section.type === "heading") return sum + section.text.length;
    if (section.type === "list") return sum + section.items.join("").length;
    if (section.type === "callout") return sum + section.text.length;
    return sum;
  }, 0);
  return Math.max(1, Math.round(totalChars / 450));
}
